import type { MetadataRoute } from "next";

// Added to a home screen, BACulator opens full-screen like an app, straight onto the night screen.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "BACulator",
    short_name: "BACulator",
    description: "Add drinks in one tap and see an estimate of your blood alcohol.",
    id: "/",
    start_url: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#09090b",
    theme_color: "#09090b",
    // Generated by scripts/make-icons.mjs from src/lib/brand-mark-svg.ts. The maskable one keeps the glyph in the 80% safe zone.
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
